1	#!/usr/bin/env node
2	// Append a timestamped snapshot of current units.json into data/snapshots/.
3	// Run via `npm run snapshot`. Designed to be safe on every run (idempotent
4	// per-day: overwrites the day's snapshot if one already exists).
5	
6	import { promises as fs } from "node:fs";
7	import path from "node:path";
8	import { fileURLToPath } from "node:url";
9	
10	const __dirname = path.dirname(fileURLToPath(import.meta.url));
11	const root = path.resolve(__dirname, "..");
12	const dataDir = path.join(root, "data");
13	const snapDir = path.join(dataDir, "snapshots");
14	
15	const unitsRaw = await fs.readFile(path.join(dataDir, "units.json"), "utf8");
16	const units = JSON.parse(unitsRaw);
17	
18	const takenAt = new Date().toISOString();
19	const dateKey = takenAt.slice(0, 10);
20	
21	const snapshot = {
22	  takenAt,
23	  unitCount: units.length,
24	  units: units.map((u) => ({
25	    id: u.id,
26	    dealerId: u.dealerId,
27	    model: u.model,
28	    trim: u.trim,
29	    askingPrice: u.dealerAskingPrice,
30	    daysOnLot: u.daysOnLot,
31	    status: u.status,
32	  })),
33	};
34	
35	await fs.mkdir(snapDir, { recursive: true });
36	const outPath = path.join(snapDir, `${dateKey}.json`);
37	await fs.writeFile(outPath, JSON.stringify(snapshot, null, 2) + "\n");
38	console.log(`Snapshot written: ${path.relative(root, outPath)} (${snapshot.unitCount} units)`);
39

1	import { ON_DEALER_FEES, PROVINCE_TAX, bcPstRateFor, type Province } from "./constants";
2	import transportBandsData from "../../data/transport-bands.json";
3	import type {
4	  Dealer,
5	  Incentive,
6	  IncentiveLine,
7	  IncentiveScope,
8	  InventoryUnit,
9	  ScoredUnit,
10	} from "./types";
11	
12	type TransportBands = {
13	  sameProvince: number;
14	  neighbour: number;
15	  regional: number;
16	  crossCountry: number;
17	  neighbours: Record<string, string[]>;
18	  regionalGroups: Record<string, string[]>;
19	};
20	const TRANSPORT_BANDS = transportBandsData as unknown as TransportBands;
21	
22	// Flat-rate transport heuristic. NOT a quote — just enough to make
23	// cross-province deals comparable on the dashboard. Adds a separate line
24	// to the OTD breakdown so the buyer can see why an Alberta deal isn't
25	// actually $2k cheaper.
26	export function transportCost(dealerProv: Province, buyerProv: Province): number {
27	  if (dealerProv === buyerProv) return TRANSPORT_BANDS.sameProvince;
28	  if (TRANSPORT_BANDS.neighbours[buyerProv]?.includes(dealerProv)) {
29	    return TRANSPORT_BANDS.neighbour;
30	  }
31	  for (const group of Object.values(TRANSPORT_BANDS.regionalGroups)) {
32	    if (group.includes(dealerProv) && group.includes(buyerProv)) {
33	      return TRANSPORT_BANDS.regional;
34	    }
35	  }
36	  return TRANSPORT_BANDS.crossCountry;
37	}
38	
39	export type { IncentiveLine } from "./types";
40	
41	// E-GMP cars are assembled in Korea (and US for some Ioniq 5 trims) so they
42	// are NOT Canadian-made. EVAP cap applies in full to every unit we track.
43	const E_GMP_IS_IMPORTED = true;
44	
45	// Cash incentive scopes that come off the OTD as a contract-level deduction.
46	// lease_promo / finance_promo are APR-based (modeled as monthly payment, not
47	// price), and charger_install is a separate budget line.
48	const OTD_ELIGIBLE_SCOPES: ReadonlySet<IncentiveScope> = new Set([
49	  "federal",
50	  "provincial",
51	  "manufacturer_cash",
52	  "loyalty",
53	  "conquest",
54	]);
55	
56	// Programs that are scoped "provincial" or similar but that pay out as a
57	// loan-rate or post-purchase reimbursement, not as a contract-line rebate.
58	// These should not be subtracted from OTD even though appliesTo matches.
59	const NON_OTD_INCENTIVE_IDS: ReadonlySet<string> = new Set([
60	  "nl-takecharge-nlcu-loan-rebate-2026",
61	]);
62	
63	// Pre-tax transaction value used for cap eligibility. Excludes sales tax
64	// (matches Transport Canada's EVAP rule).
65	export function preTaxTransactionValue(unit: InventoryUnit): number {
66	  return (
67	    unit.dealerAskingPrice +
68	    unit.freightPdi +
69	    ON_DEALER_FEES.airConditioningExciseTax
70	  );
71	}
72	
73	// Pre-tax value AFTER manufacturer cash has been applied. EVAP's $50k cap is
74	// measured against the contract value at signing — a $58k Ioniq 6 with a
75	// $16k OEM bonus is a $42k contract and therefore EVAP-eligible.
76	export function effectivePreTaxValue(
77	  unit: InventoryUnit,
78	  applicable: Incentive[] = [],
79	): number {
80	  const oemCash = applicable
81	    .filter(
82	      (i) =>
83	        i.scope === "manufacturer_cash" &&
84	        i.status === "active" &&
85	        i.amountCad !== undefined,
86	    )
87	    .reduce((s, i) => s + (i.amountCad ?? 0), 0);
88	  return Math.max(0, preTaxTransactionValue(unit) - oemCash);
89	}
90	
91	export function evapEligibleAmount(
92	  unit: InventoryUnit,
93	  evap: Incentive | undefined,
94	  applicable: Incentive[] = [],
95	): number {
96	  if (!evap || evap.status !== "active") return 0;
97	  const cap = evap.transactionValueCapCad;
98	  if (cap !== undefined && evap.capAppliesToImported && E_GMP_IS_IMPORTED) {
99	    if (effectivePreTaxValue(unit, applicable) > cap) return 0;
100	  }
101	  // Cash/finance/48mo+ lease assumption (default in the dashboard view).
102	  return evap.leaseTermProration?.["48"] ?? evap.amountCad ?? 0;
103	}
104	
105	// Walks the matched-applicable list and returns the per-line dollar amounts
106	// that come off the OTD, plus the total. EVAP's lease-term proration and
107	// post-OEM-cash cap check live inside evapEligibleAmount.
108	export function stackedOtdIncentives(
109	  unit: InventoryUnit,
110	  applicable: Incentive[],
111	): { lines: IncentiveLine[]; totalCad: number } {
112	  const lines: IncentiveLine[] = [];
113	  for (const inc of applicable) {
114	    if (NON_OTD_INCENTIVE_IDS.has(inc.id)) continue;
115	    if (!OTD_ELIGIBLE_SCOPES.has(inc.scope)) continue;
116	    if (inc.status !== "active") continue;
117	    let amount = 0;
118	    if (inc.id.startsWith("fed-evap")) {
119	      amount = evapEligibleAmount(unit, inc, applicable);
120	    } else if (inc.amountCad !== undefined) {
121	      amount = inc.amountCad;
122	    }
123	    if (amount > 0) {
124	      lines.push({ id: inc.id, name: inc.name, scope: inc.scope, amountCad: amount });
125	    }
126	  }
127	  const totalCad = +lines.reduce((s, l) => s + l.amountCad, 0).toFixed(2);
128	  return { lines, totalCad };
129	}
130	
131	// Sales tax handler. ON: flat HST. BC: 5% GST + progressive PST bracket
132	// keyed off the pre-tax base. Other provinces: flat PROVINCE_TAX rate.
133	function salesTaxFor(province: string, preTaxBase: number, vehiclePrice: number): number {
134	  if (province === "BC") {
135	    const gst = preTaxBase * 0.05;
136	    const pst = vehiclePrice * bcPstRateFor(vehiclePrice);
137	    return +(gst + pst).toFixed(2);
138	  }
139	  const rate = PROVINCE_TAX[province as keyof typeof PROVINCE_TAX] ?? 0.13;
140	  return +(preTaxBase * rate).toFixed(2);
141	}
142	
143	// True out-the-door math for a single unit. The buyer-relevant total.
144	// All cash-equivalent incentives (federal EVAP, provincial rebates,
145	// manufacturer cash, loyalty/conquest) are subtracted as contract-line
146	// deductions. APR-based promos and charger-install programs are excluded.
147	// Sales tax stacks on top of the pre-tax base (vehicle + freight + AC
148	// excise) per CRA guidance; OMVIC, RDPRM, tire stewardship, and licensing
149	// are typically post-tax line items.
150	//
151	// buyerProvince is what the buyer pays sales tax in (NOT the dealer's
152	// province) — cross-province purchases pay tax at the buyer's destination
153	// rate, not the seller's. Defaults to the dealer's province for backward
154	// compat, but every caller in the app should pass the real buyer province.
155	// Transport cost line added when buyer != dealer province.
156	export function computeOtd(
157	  unit: InventoryUnit,
158	  dealer: Dealer,
159	  applicable: Incentive[] = [],
160	  buyerProvince?: Province,
161	): ScoredUnit["otdBreakdown"] {
162	  const taxProv = buyerProvince ?? dealer.province;
163	  const dealerAdjustment = unit.dealerAskingPrice - unit.msrp;
164	  const preTaxBase = preTaxTransactionValue(unit);
165	  const salesTax = salesTaxFor(taxProv, preTaxBase, unit.dealerAskingPrice);
166	  const transport = transportCost(dealer.province, taxProv);
167	
168	  const stack = stackedOtdIncentives(unit, applicable);
169	
170	  const total =
171	    preTaxBase +
172	    salesTax +
173	    transport +
174	    ON_DEALER_FEES.rdprmFee +
175	    ON_DEALER_FEES.omvicFee +
176	    ON_DEALER_FEES.tireStewardshipFee +
177	    ON_DEALER_FEES.govLicensingEstimate -
178	    stack.totalCad;
179	
180	  return {
181	    msrp: unit.msrp,
182	    freightPdi: unit.freightPdi,
183	    dealerAdjustment,
184	    acExciseTax: ON_DEALER_FEES.airConditioningExciseTax,
185	    rdprm: ON_DEALER_FEES.rdprmFee,
186	    omvic: ON_DEALER_FEES.omvicFee,
187	    tireStewardship: ON_DEALER_FEES.tireStewardshipFee,
188	    govLicensing: ON_DEALER_FEES.govLicensingEstimate,
189	    salesTax,
190	    transportCost: transport,
191	    salesTaxProvince: taxProv,
192	    incentivesApplied: stack.lines,
193	    incentivesTotalCad: stack.totalCad,
194	    total: +total.toFixed(2),
195	  };
196	}
197	
198	// Filter incentives down to ones that match this unit + dealer. Used both
199	// for the deal-score stack term and for the per-unit detail panel. EVAP
200	// transaction-value cap is enforced here so over-cap units don't show the
201	// rebate as "applicable." Cap is measured against the post-OEM-cash contract
202	// value, so a $58k Limited AWD with a $16k OEM bonus still gets EVAP.
203	export function applicableIncentives(
204	  unit: InventoryUnit,
205	  dealer: Dealer,
206	  incentives: Incentive[],
207	): Incentive[] {
208	  // First pass: filter on appliesTo + status (no cap check yet).
209	  const matched = incentives.filter((inc) => {
210	    if (inc.status === "ended") return false;
211	    const a = inc.appliesTo;
212	    if (a) {
213	      if (a.models && !a.models.includes(unit.model)) return false;
214	      if (a.trims && !a.trims.includes(unit.trim)) return false;
215	      if (a.years && !a.years.includes(unit.year)) return false;
216	      if (a.provinces && !a.provinces.includes(dealer.province)) return false;
217	    }
218	    return true;
219	  });
220	
221	  // Second pass: drop incentives that fail the post-OEM-cash transaction-
222	  // value cap. Computed once over the matched set.
223	  const adjustedPreTax = effectivePreTaxValue(unit, matched);
224	  return matched.filter((inc) => {
225	    if (
226	      inc.transactionValueCapCad !== undefined &&
227	      inc.capAppliesToImported &&
228	      E_GMP_IS_IMPORTED &&
229	      adjustedPreTax > inc.transactionValueCapCad
230	    ) {
231	      return false;
232	    }
233	    return true;
234	  });
235	}
236	
237	// Helper exposed for UI: how far over the cap is this unit (0 if eligible)?
238	// Uses post-OEM-cash value so it matches the eligibility check.
239	export function evapCapDeltaCad(
240	  unit: InventoryUnit,
241	  evap: Incentive | undefined,
242	  applicable: Incentive[] = [],
243	): number {
244	  if (!evap || evap.transactionValueCapCad === undefined) return 0;
245	  const delta = effectivePreTaxValue(unit, applicable) - evap.transactionValueCapCad;
246	  return delta > 0 ? +delta.toFixed(2) : 0;
247	}
248	
249	// Component scores are 0-1; the composite is a weighted average rendered as 0-100.
250	function priceVsMsrpScore(unit: InventoryUnit): number {
251	  const ratio = unit.dealerAskingPrice / unit.msrp;
252	  // 1.0 = exact MSRP -> 0.5; 5% below MSRP -> ~1.0; 3% above -> ~0.0
253	  const score = 0.5 + (1 - ratio) * 10;
254	  return clamp01(score);
255	}
256	
257	function daysOnLotScore(unit: InventoryUnit): number {
258	  const d = unit.daysOnLot ?? 0;
259	  // 0 days -> 0; 60 days -> ~0.6; 120+ days -> 1.0 (very negotiable)
260	  return clamp01(d / 120);
261	}
262	
263	// "Pressure" = how leverageable a dealer is for a buyer. High pressure when:
264	// they hold a deep cluster of similar trims and at least some are aging out.
265	export function dealerPressureIndex(
266	  unit: InventoryUnit,
267	  dealerUnits: InventoryUnit[],
268	): number {
269	  const sameTrim = dealerUnits.filter(
270	    (u) => u.model === unit.model && u.trim === unit.trim,
271	  );
272	  if (sameTrim.length === 0) return 0;
273	  const depth = Math.min(sameTrim.length / 4, 1); // 4+ same-trim = max depth signal
274	  const avgAge =
275	    sameTrim.reduce((s, u) => s + (u.daysOnLot ?? 0), 0) / sameTrim.length;
276	  const ageSignal = clamp01(avgAge / 90);
277	  // Equal weight; both signals must be present for a high score.
278	  return clamp01(0.5 * depth + 0.5 * ageSignal);
279	}
280	
281	function incentiveStackScore(applicable: Incentive[]): number {
282	  if (applicable.length === 0) return 0;
283	  const cashTotal = applicable
284	    .filter((i) => i.amountCad && i.status === "active")
285	    .reduce((s, i) => s + (i.amountCad ?? 0), 0);
286	  // $0 -> 0; $10k+ stack -> 1.0
287	  return clamp01(cashTotal / 10000);
288	}
289	
290	export function computeDealScore(args: {
291	  unit: InventoryUnit;
292	  dealer: Dealer;
293	  dealerUnits: InventoryUnit[];
294	  applicable: Incentive[];
295	}) {
296	  const priceVsMsrp = priceVsMsrpScore(args.unit);
297	  const daysOnLot = daysOnLotScore(args.unit);
298	  const dealerPressure = dealerPressureIndex(args.unit, args.dealerUnits);
299	  const incentiveStack = incentiveStackScore(args.applicable);
300	
301	  // Weights chosen so that price discount and incentive stack matter most;
302	  // pressure and aging shift the score 10-20 points either way.
303	  const composite =
304	    priceVsMsrp * 0.35 +
305	    incentiveStack * 0.3 +
306	    dealerPressure * 0.2 +
307	    daysOnLot * 0.15;
308	
309	  return {
310	    score: Math.round(composite * 100),
311	    breakdown: {
312	      priceVsMsrp: Math.round(priceVsMsrp * 100),
313	      daysOnLot: Math.round(daysOnLot * 100),
314	      dealerPressure: Math.round(dealerPressure * 100),
315	      incentiveStack: Math.round(incentiveStack * 100),
316	    },
317	  };
318	}
319	
320	function clamp01(n: number): number {
321	  if (Number.isNaN(n)) return 0;
322	  if (n < 0) return 0;
323	  if (n > 1) return 1;
324	  return n;
325	}
